{"action":"edit","path":"toolformer_filter.py","old_text":"","new_text":"import numpy as np

def filter_api_calls(log_probs_empty, log_probs_call_only, log_probs_plus, tau_filter):
    # Validate matrices
    matrices = [log_probs_empty, log_probs_call_only, log_probs_plus]
    for mat in matrices:
        if not isinstance(mat, np.ndarray):
            raise ValueError("Input must be numpy arrays")
        if mat.ndim != 2:
            raise ValueError("Input must be 2D")
        if mat.shape[0] == 0 or mat.shape[1] == 0:
            raise ValueError("Input must not be empty")
        if np.any(np.isnan(mat)) or np.any(np.isinf(mat)):
            raise ValueError("Input must be finite")
        if np.any(mat > 0):
            raise ValueError("Log probabilities must be nonpositive")
    if not (log_probs_empty.shape == log_probs_call_only.shape == log_probs_plus.shape):
        raise ValueError("All matrices must have same shape")
    if isinstance(tau_filter, bool):
        raise ValueError("tau_filter cannot be boolean")
    if not np.isscalar(tau_filter) or np.isnan(tau_filter) or np.isinf(tau_filter) or tau_filter < 0:
        raise ValueError("tau_filter must be finite nonnegative scalar")

    n_candidates, future_horizon = log_probs_empty.shape
    t = np.arange(future_horizon)
    raw_weights = np.maximum(0, 1 - 0.2 * t)
    normalized_weights = raw_weights / np.sum(raw_weights)

    loss_empty = -np.dot(log_probs_empty, normalized_weights)
    loss_call_only = -np.dot(log_probs_call_only, normalized_weights)
    loss_plus = -np.dot(log_probs_plus, normalized_weights)

    L_minus = np.minimum(loss_empty, loss_call_only)
    margin = L_minus - loss_plus
    keep = margin >= tau_filter

    return keep, margin"}
